import KibaShield from '../components/KibaShield';
import Footer from '../components/Footer';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const EyeIcon = ({ show }) => show ? (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
    <path d="M12 5C7 5 2.73 8.11 1 12.5C2.73 16.89 7 20 12 20C17 20 21.27 16.89 23 12.5C21.27 8.11 17 5 12 5Z" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <circle cx="12" cy="12.5" r="3.5" stroke="#00B4D8" strokeWidth="2"/>
    <circle cx="12" cy="12.5" r="1.5" fill="#00B4D8"/>
  </svg>
) : (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
    <path d="M2 2L22 22" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round"/>
    <path d="M6.71 6.71C4.56 8.08 2.9 10.11 2 12.5C3.73 16.89 8 20 13 20" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9.88 4.13C10.57 4.05 11.28 4 12 4C17 4 21.27 7.11 23 11.5" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9.76 9.76C9.29 10.23 9 10.88 9 11.6C9 13.14 10.35 14.4 12 14.4C12.76 14.4 13.45 14.12 13.96 13.66" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

const strengthInfo = (pwd) => {
  if (!pwd) return null;
  if (pwd.length < 6) return { label: 'Too short', color: '#EF233C', width: '20%' };
  if (pwd.length < 8) return { label: 'Weak', color: '#FFB703', width: '40%' };
  if (!/[A-Z]/.test(pwd) || !/[0-9]/.test(pwd)) return { label: 'Fair', color: '#FFB703', width: '60%' };
  return { label: 'Strong', color: '#06D6A0', width: '100%' };
};

const Register = () => {
  const { login, darkMode } = useAuth();
  const navigate = useNavigate();
  const [fullName, setFullName] = useState('');
  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [role, setRole] = useState('customer');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [pose, setPose] = useState(1);
  const [shieldState, setShieldState] = useState('idle');

  const strength = strengthInfo(password);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!fullName || !identifier || !password) {
      setError('Please fill in all fields');
      setPose(3); setShieldState('warning');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
      return;
    }
    if (password.length < 6) {
      setError('Password must be at least 6 characters');
      setPose(3); setShieldState('warning');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
      return;
    }
    setLoading(true); setPose(7); setShieldState('idle');
    try {
      const res = await axios.post(`${API}/api/auth/register`, { fullName, identifier, password, role });
      setPose(2); setShieldState('success');
      confetti({ particleCount: 250, spread: 120, origin: { y: 0.5 }, colors: ['#06D6A0', '#00B4D8', '#FF6B35', '#FFB703'] });
      setTimeout(() => {
        login(res.data.user, res.data.token);
        const r = res.data.user.role;
        navigate(r === 'admin' ? '/admin' : r === 'staff' ? '/staff' : '/dashboard');
      }, 1800);
    } catch (err) {
      setError(err.response?.data?.message || 'Something went wrong. Please try again.');
      setPose(4); setShieldState('danger');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
    } finally { setLoading(false); }
  };

  const inputStyle = {
    width: '100%', padding: '14px 16px', border: '2px solid #E0F2FE', borderRadius: '12px',
    fontSize: '15px', fontFamily: 'Inter, sans-serif',
    background: darkMode ? '#0F172A' : '#F0F9FF',
    color: darkMode ? '#F1F5F9' : '#0F172A',
    outline: 'none', boxSizing: 'border-box', transition: 'border-color 0.2s'
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: darkMode ? '#0F172A' : '#F0F9FF' }}>
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '32px 16px' }}>
        <div style={{ display: 'flex', gap: '48px', alignItems: 'center', width: '100%', maxWidth: '960px', flexWrap: 'wrap', justifyContent: 'center' }}>

          <div className="animate-slideInLeft" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '24px' }}>
            <div style={{ position: 'relative', display: 'flex', alignItems: 'flex-end', gap: '16px' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                <div className="speech-bubble animate-bubblePop" style={{ maxWidth: '130px', fontSize: '11px', fontWeight: 700, color: '#EC4899', border: '2px solid #EC4899' }}>
                  Heh heh... I can read minds! ⭐
                </div>
                <img src="/images/char-anya-excited.png" alt="Anya" className="animate-float" style={{ width: '100px', height: '140px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(236,72,153,0.3))' }}
                  onError={e => e.target.style.display = 'none'} />
              </div>
              <KibaShield pose={pose} shieldState={shieldState} customLabel={loading ? 'Creating your account...' : null} />
            </div>
            <div style={{ textAlign: 'center' }}>
              <h1 style={{ fontSize: '28px', fontWeight: 900, color: darkMode ? '#F1F5F9' : '#0F172A', margin: 0 }}>KibaliGuard</h1>
              <p style={{ color: '#64748B', fontSize: '14px', marginTop: '4px' }}>Your data. Your rules. Your control.</p>
            </div>
          </div>

          <div className="animate-slideInRight" style={{ background: darkMode ? '#1E293B' : '#fff', borderRadius: '24px', padding: '44px 40px', boxShadow: '0 8px 48px rgba(0,0,0,0.1)', width: '100%', maxWidth: '420px', border: '1.5px solid #E0F2FE' }}>
            <h2 style={{ fontSize: '28px', fontWeight: 900, color: darkMode ? '#F1F5F9' : '#0F172A', marginBottom: '6px', letterSpacing: '-0.5px' }}>Create account</h2>
            <p style={{ color: '#64748B', fontSize: '14px', marginBottom: '28px' }}>Join KibaliGuard and take control of your data</p>

            {error && (
              <div className="animate-slideUp" style={{ background: '#FEF2F2', color: '#EF233C', border: '1.5px solid #FECACA', borderRadius: '12px', padding: '13px 16px', fontSize: '14px', marginBottom: '20px' }}>
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit}>
              {[
                { label: 'Full name', value: fullName, set: setFullName, type: 'text', placeholder: 'Enter your full name' },
                { label: 'Email or phone number', value: identifier, set: e => { setIdentifier(e); if (e.length > 0) setPose(8); else setPose(1); }, type: 'text', placeholder: 'your@email.com or 07XXXXXXXX' },
              ].map(field => (
                <div key={field.label} style={{ marginBottom: '20px' }}>
                  <label style={{ display: 'block', fontWeight: 700, fontSize: '13px', color: darkMode ? '#CBD5E1' : '#0F172A', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>{field.label}</label>
                  <input type={field.type} placeholder={field.placeholder} value={field.value}
                    onChange={e => typeof field.set === 'function' ? field.set(e.target.value) : null}
                    style={inputStyle}
                    onFocus={e => e.target.style.borderColor = '#00B4D8'}
                    onBlur={e => e.target.style.borderColor = '#E0F2FE'}
                  />
                </div>
              ))}

              <div style={{ marginBottom: '8px' }}>
                <label style={{ display: 'block', fontWeight: 700, fontSize: '13px', color: darkMode ? '#CBD5E1' : '#0F172A', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Password</label>
                <div style={{ position: 'relative' }}>
                  <input type={showPassword ? 'text' : 'password'} placeholder="Create a strong password" value={password}
                    onChange={e => setPassword(e.target.value)}
                    onFocus={() => setPose(9)}
                    onBlur={() => { if (identifier.length > 0) setPose(8); else setPose(1); }}
                    style={{ ...inputStyle, paddingRight: '48px' }}
                  />
                  <button type="button" onClick={() => setShowPassword(p => !p)}
                    style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', cursor: 'pointer', padding: '4px', display: 'flex' }}>
                    <EyeIcon show={showPassword} />
                  </button>
                </div>
              </div>

              {strength && (
                <div style={{ marginBottom: '20px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '6px' }}>
                    <span style={{ fontSize: '12px', color: '#64748B', fontWeight: 500 }}>Password strength</span>
                    <span style={{ fontSize: '12px', fontWeight: 800, color: strength.color }}>{strength.label}</span>
                  </div>
                  <div style={{ height: '5px', background: '#E0F2FE', borderRadius: '999px', overflow: 'hidden' }}>
                    <div style={{ height: '100%', width: strength.width, background: strength.color, borderRadius: '999px', transition: 'all 0.3s ease' }} />
                  </div>
                </div>
              )}

              <div style={{ marginBottom: '28px' }}>
                <label style={{ display: 'block', fontWeight: 700, fontSize: '13px', color: darkMode ? '#CBD5E1' : '#0F172A', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Account type</label>
                <select value={role} onChange={e => setRole(e.target.value)} style={inputStyle}
                  onFocus={e => e.target.style.borderColor = '#00B4D8'}
                  onBlur={e => e.target.style.borderColor = '#E0F2FE'}>
                  <option value="customer">Job Applicant / Customer</option>
                  <option value="staff">HR Staff / Recruiter</option>
                  <option value="admin">Administrator</option>
                </select>
              </div>

              <button type="submit" disabled={loading}
                style={{ width: '100%', padding: '15px', background: loading ? '#00B4D8' : '#FF6B35', color: '#fff', border: 'none', borderRadius: '14px', fontWeight: 800, fontSize: '16px', cursor: loading ? 'not-allowed' : 'pointer', fontFamily: 'Inter, sans-serif', marginBottom: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '10px', boxShadow: '0 8px 24px rgba(255,107,53,0.35)', transition: 'all 0.2s' }}>
                {loading ? (
                  <>
                    <span style={{ width: '18px', height: '18px', border: '3px solid rgba(255,255,255,0.3)', borderTop: '3px solid #fff', borderRadius: '50%', display: 'inline-block', animation: 'kibashield-spin 0.8s linear infinite' }} />
                    Creating your account...
                  </>
                ) : 'Create Account'}
              </button>
            </form>

            <div style={{ textAlign: 'center', fontSize: '14px', color: '#64748B' }}>
              Already have an account?{' '}
              <Link to="/login" style={{ color: '#FF6B35', fontWeight: 800, textDecoration: 'none' }}>Sign in here</Link>
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default Register;
